var CUISINE_BY_ID = Object.fromEntries(CUISINES.map((c) => [c.id, c]));
function dishesFor(cuisine, courseId, { vegOnly = false } = {}) {
  const items = cuisine?.courses?.[courseId] ?? [];
  return vegOnly ? items.filter((d) => d.veg) : items;
}

